# builder/gen_ch22_p1.py
# -*- coding: utf-8 -*-

exercises = [{'num': 1, 'title': 'Ручная отмена контекста через context.WithCancel и сигнал <-ctx.Done()', 'task': '**Ручная отмена (`context.WithCancel`)**: Создайте контекст с возможностью отмены. Запустите фоновую горутину, которая в цикле `for` выполняет фоновую работу (например, раз в секунду). Горутина должна проверять канал `<-ctx.Done()`. В основной горутине подождите 3 секунды и вызовите функцию `cancel()`. Убедитесь, что фоновая горутина корректно завершила работу.', 'theory': 'Пакет `context` — стандартный механизм управления жизненным циклом горутин, передачи дедлайнов и метаданных запроса в Go. Функция `context.WithCancel(parent)` возвращает производный контекст `ctx` и функцию отмены `cancel()`. Вызов `cancel()` закрывает внутренний канал `<-ctx.Done()`, широковещательно оповещая все подписанные горутины о необходимости прекратить работу.', 'step_by_step': '1. Создадим родительский контекст `ctx, cancel := context.WithCancel(context.Background())`.\n2. Обязательно вызовем `defer cancel()` для гарантии освобождения ресурсов.\n3. Запустим горутину с циклом `for select`, слушающую `<-ctx.Done()` и тикер.\n4. В `main` вызовем `cancel()` и дождемся завершения горутины через `sync.WaitGroup`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc worker(ctx context.Context, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Println("[Worker] Фоновая задача запущена...")\n\n\tticker := time.NewTicker(20 * time.Millisecond)\n\tdefer ticker.Stop()\n\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done(): // Срабатывает мгновенно при вызове cancel()\n\t\t\tfmt.Printf("[Worker] Получен сигнал отмены: %v. Завершаю работу!\\n", ctx.Err())\n\t\t\treturn\n\t\tcase t := <-ticker.C:\n\t\t\tfmt.Printf("[Worker] Обработка пакета данных в %s\\n", t.Format("15:04:05.000"))\n\t\t}\n\t}\n}\n\nfunc main() {\n\t// 1. Создаем контекст с функцией отмены\n\tctx, cancel := context.WithCancel(context.Background())\n\tdefer cancel() // Защита от утечки ресурсов\n\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\tgo worker(ctx, &wg)\n\n\t// Имитируем работу приложения в течение 50 мс\n\ttime.Sleep(50 * time.Millisecond)\n\n\tfmt.Println("\\n[Main] Инициирую отмену контекста: вызов cancel()...")\n\tcancel()\n\n\twg.Wait()\n\tfmt.Println("[Main] Воркер успешно и безопасно остановлен!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker] Фоновая задача запущена...\n# [Worker] Обработка пакета данных в 15:04:05.020\n# [Worker] Обработка пакета данных в 15:04:05.040\n# \n# [Main] Инициирую отмену контекста: вызов cancel()...\n# [Worker] Получен сигнал отмены: context canceled. Завершаю работу!\n# [Main] Воркер успешно и безопасно остановлен!'}], 'under_the_hood': '`context.WithCancel` создает структуру `cancelCtx`. При вызове `cancel()` мьютекс `cancelCtx.mu` блокируется, внутренний канал `done` закрывается через `close()`, поле `err` заполняется ошибкой `context.Canceled`, и отмена каскадно передается всем дочерним контекстам.', 'pitfalls': 'Забытый вызов `cancel()` оставляет дочерний контекст зарегистрированным в дереве родителя до завершения родительского контекста (Context Leak).', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы гарантии потокобезопасности методов пакета context?»\n**Ответ:** Все методы интерфейса `context.Context` (`Deadline()`, `Done()`, `Err()`, `Value()`), а также функции `cancel()` полностью потокобезопасны и могут вызываться одновременно из сотен параллельных горутин без внешней синхронизации.'}, {'num': 2, 'title': 'Управление дедлайнами операций: context.WithTimeout и context.DeadlineExceeded', 'task': '**Таймаут операции (`context.WithTimeout`)**: Напишите функцию, имитирующую тяжелый сетевой запрос, занимающий 5 секунд. Вызовите эту функцию с контекстом, у которого установлен таймаут в 2 секунды. Функция должна вернуть ошибку `context.DeadlineExceeded` по истечении таймаута.', 'theory': '`context.WithTimeout(parent, duration)` автоматически инициирует отмену по истечении заданного интервала времени. Метод `ctx.Err()` в этом случае возвращает стандартную ошибку-синглтон `context.DeadlineExceeded`.', 'step_by_step': '1. Создадим функцию `slowNetworkCall(ctx context.Context) error`.\n2. Внутри функции используем `select` между `time.After(...)` и `ctx.Done()`.\n3. В `main` вызовем функцию с таймаутом 40 мс.\n4. Проверим тип и текст ошибки через `errors.Is(err, context.DeadlineExceeded)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"time"\n)\n\nfunc slowNetworkCall(ctx context.Context) error {\n\tfmt.Println("[Client] Отправка тяжелого RPC-запроса (требуется ~200мс)...")\n\n\tselect {\n\tcase <-time.After(200 * time.Millisecond):\n\t\tfmt.Println("[Client] Ответ от сервера успешно получен!")\n\t\treturn nil\n\tcase <-ctx.Done(): // Срабатывает по истечении таймаута контекста\n\t\treturn ctx.Err()\n\t}\n}\n\nfunc main() {\n\t// Контекст с жестким таймаутом 40 мс\n\tctx, cancel := context.WithTimeout(context.Background(), 40*time.Millisecond)\n\tdefer cancel()\n\n\terr := slowNetworkCall(ctx)\n\tif err != nil {\n\t\tif errors.Is(err, context.DeadlineExceeded) {\n\t\t\tfmt.Printf("[Main] ОШИБКА: Превышен таймаут операции: %v\\n", err)\n\t\t} else {\n\t\t\tfmt.Printf("[Main] Ошибка запроса: %v\\n", err)\n\t\t}\n\t} else {\n\t\tfmt.Println("[Main] Запрос выполнен успешно.")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Отправка тяжелого RPC-запроса (требуется ~200мс)...\n# [Main] ОШИБКА: Превышен таймаут операции: context deadline exceeded'}], 'under_the_hood': '`context.WithTimeout` внутри оборачивает `context.WithDeadline(parent, time.Now().Add(timeout))` и запускает системный таймер `time.AfterFunc`.', 'pitfalls': 'Всегда проверяйте ошибки контекста через `errors.Is(err, context.DeadlineExceeded)`, а не строковым сравнением `err.Error() == "..."`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между context.Canceled и context.DeadlineExceeded?»\n**Ответ:** `context.Canceled` возвращается при явном ручном вызове функции `cancel()`. `context.DeadlineExceeded` возвращается, когда автоматически истек дедлайн или таймаут контекста.'}, {'num': 3, 'title': 'Передача Request-Scoped метаданных через context.WithValue', 'task': '**Передача метаданных (`context.WithValue`)**: Создайте цепочку вызовов функций (например, `Middleware -> Handler -> Controller`). Положите в контекст на самом верхнем уровне уникальный ID запроса (`RequestID`). Извлеките и выведите его на самом глубоком уровне в контроллере. Объясните, почему не стоит использовать контекст для передачи опциональных параметров бизнес-логики.', 'theory': '`context.WithValue(parent, key, val)` создает неизменяемый узел дерева контекстов, хранящий пару ключ-значение. Поиск значения `ctx.Value(key)` рекурсивно поднимается от текущего узла к корню ($O(K)$ глубина дерева). Контекст предназначен строго для сквозных метаданных запроса (Request ID, Trace ID, Security Token), а не для передачи параметров бизнес-логики.', 'step_by_step': '1. Объявим пользовательский тип ключа `type ctxKey string`.\n2. В функции `authMiddleware` добавим `RequestID` в контекст.\n3. Передадим `ctx` через `httpHandler` в `dbController`.\n4. Извлечем значение через `ctx.Value()` с типобезопасным приведением.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n)\n\n// Неэкспортируемый тип для ключа контекста исключает коллизии между пакетами\ntype contextKey string\n\nconst requestIDKey contextKey = "request_id"\n\nfunc authMiddleware(ctx context.Context) {\n\t// Обогащаем контекст сквозным Request ID\n\treqCtx := context.WithValue(ctx, requestIDKey, "req-uuid-9842-prod")\n\thttpHandler(reqCtx)\n}\n\nfunc httpHandler(ctx context.Context) {\n\tfmt.Println("[Handler] Обработка HTTP-запроса...")\n\tdbController(ctx)\n}\n\nfunc dbController(ctx context.Context) {\n\t// Извлечение значения из контекста\n\tif val := ctx.Value(requestIDKey); val != nil {\n\t\treqID, ok := val.(string)\n\t\tif ok {\n\t\t\tfmt.Printf("[DB Controller] Выполнение SQL-запроса для RequestID: %q\\n", reqID)\n\t\t\treturn\n\t\t}\n\t}\n\tfmt.Println("[DB Controller] RequestID не найден в контексте")\n}\n\nfunc main() {\n\trootCtx := context.Background()\n\tauthMiddleware(rootCtx)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Handler] Обработка HTTP-запроса...\n# [DB Controller] Выполнение SQL-запроса для RequestID: "req-uuid-9842-prod" '}], 'under_the_hood': '`valueCtx` хранит ровно одну пару `(key, val)` и ссылку на `parent`. Поиск значения выполняется линейным обходом родителей до корня.', 'pitfalls': 'Использование контекста для передачи бизнес-аргументов (User ID, фильтры поиска) скрывает сигнатуры функций, ломает статическую типизацию компилятора и усложняет модульное тестирование.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему нельзя использовать стандартные строки string в качестве ключей для context.WithValue?»\n**Ответ:** Потому что разные независимые пакеты и библиотеки могут случайно использовать одинаковую строку (например, `"user_id"`), перезаписывая чужие данные. Использование кастомного типа `type keyType struct{}` гарантирует уникальность ключа в рантайме.'}, {'num': 4, 'title': 'Прерывание сетевой операции по таймауту context.WithTimeout', 'task': 'Используй `context.WithTimeout()`. Запусти HTTP-запрос (или `time.Sleep`) в горутине. Если не успевает за 2 секунды — `ctx.Done()` срабатывает, программа выводит `"timeout"`.', 'theory': 'Шаблон асинхронного ожидания: запуск задачи в горутине с одновременным прослушиванием `<-ctx.Done()` в главном потоке.', 'step_by_step': '1. Создадим `ctx, cancel := context.WithTimeout(context.Background(), 30*time.Millisecond)`.\n2. Запустим фоновую задачу, длящуюся 100 мс, возвращающую результат в канал.\n3. В `select` дождемся либо результата, либо `<-ctx.Done()`.\n4. Выведем сообщение `"timeout"`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tctx, cancel := context.WithTimeout(context.Background(), 30*time.Millisecond)\n\tdefer cancel()\n\n\tresultChan := make(chan string, 1) // Буфер = 1 исключает утечку горутины\n\n\tgo func() {\n\t\ttime.Sleep(100 * time.Millisecond) // Симуляция долгого I/O\n\t\tresultChan <- "HTTP 200 OK: Data Received"\n\t}()\n\n\tselect {\n\tcase res := <-resultChan:\n\t\tfmt.Printf("Результат: %s\\n", res)\n\tcase <-ctx.Done():\n\t\tfmt.Printf("timeout: Операция прервана по дедлайну (%v)\\n", ctx.Err())\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# timeout: Операция прервана по дедлайну (context deadline exceeded)'}], 'under_the_hood': '`<-ctx.Done()` разблокирует `select` без аллокаций памяти.', 'pitfalls': 'Всегда делайте канал `resultChan` буферизованным (`make(chan T, 1)`), чтобы фоновая горутина не зависла навсегда при срабатывании таймаута.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если вызвать cancel() дважды на одном контексте?»\n**Ответ:** Ничего плохого: функция `cancel()` абсолютно идемпотентна. Повторные вызовы мгновенно завершаются без паник и повторных блокировок.'}, {'num': 5, 'title': 'Проверка отмены контекста в синхронном цикле: ProcessWithContext', 'task': 'Напиши функцию `ProcessWithContext(ctx context.Context, data []int) (int, error)`, которая суммирует числа, но проверяет `ctx.Err()` в цикле. Если контекст отменён — верни ошибку немедленно.', 'theory': 'Для синхронных вычислений без каналов проверка `ctx.Err() != nil` внутри тела цикла является главным способом поддержания отзывчивости (Cooperative Cancellation). Если клиент разорвал соединение, процессор не тратит ресурсы на продолжение счета.', 'step_by_step': '1. Объявим `ProcessWithContext(ctx context.Context, data []int) (int, error)`.\n2. В цикле `for` на каждой итерации проверяем `if err := ctx.Err(); err != nil { return 0, err }`.\n3. Проверим работу с отмененным контекстом.\n4. Проверим работу с валидным контекстом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc ProcessWithContext(ctx context.Context, data []int) (int, error) {\n\tsum := 0\n\tfor idx, val := range data {\n\t\t// Регулярная проверка отмены контекста в тяжелом цикле\n\t\tif err := ctx.Err(); err != nil {\n\t\t\treturn 0, fmt.Errorf("обработка прервана на элементе [%d]: %w", idx, err)\n\t\t}\n\n\t\tsum += val\n\t\ttime.Sleep(10 * time.Millisecond) // Имитация вычислений\n\t}\n\treturn sum, nil\n}\n\nfunc main() {\n\tnumbers := []int{10, 20, 30, 40, 50, 60, 70, 80}\n\n\t// 1. Успешная обработка\n\tres, err := ProcessWithContext(context.Background(), numbers[:3])\n\tfmt.Printf("1. Успешный результат: sum=%d, err=%v\\n", res, err)\n\n\t// 2. Прерывание по таймауту\n\tctxTimeout, cancel := context.WithTimeout(context.Background(), 25*time.Millisecond)\n\tdefer cancel()\n\n\tres, err = ProcessWithContext(ctxTimeout, numbers)\n\tfmt.Printf("2. Прерванный результат: sum=%d, err=%v\\n", res, err)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Успешный результат: sum=60, err=<nil>\n# 2. Прерванный результат: sum=0, err=обработка прервана на элементе [2]: context deadline exceeded'}], 'under_the_hood': '`ctx.Err()` производит атомарное чтение поля ошибки без захвата тяжелых системных блокировок.', 'pitfalls': 'Если итерации сверхбыстрые (наносекунды), проверку `ctx.Err()` вызывают не на каждой итерации, а раз в $N$ шагов (`if i % 1000 == 0`), чтобы снизить оверхед.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему проверка ctx.Err() внутри CPU-bound цикла критически важна в микросервисах?»\n**Ответ:** Если входящий HTTP/gRPC запрос был отменен клиентом (клиент закрыл вкладку), сервис без проверки `ctx.Err()` продолжит выполнять тяжелые вычисления, сжигая CPU и забивая очередь других пользователей.'}, {'num': 6, 'title': 'Предотвращение утечек горутин-генераторов через ctx.Done() в select', 'task': '**Обработка `ctx.Done()` в `select`**: Напишите горутину-генератор случайных чисел, которая бесконечно пишет числа в канал. Настройте `select` внутри генератора так, чтобы при получении сигнала из `ctx.Done()` генератор закрывал свой канал и завершал работу, предотвращая утечку ресурсов.', 'theory': 'Бесконечные генераторы обязаны принимать `ctx context.Context`. Отправка в канал внутри генератора всегда оборачивается в `select`:\n```go\nselect {\ncase out <- val:\ncase <-ctx.Done():\n    return\n}\n```', 'step_by_step': '1. Создадим функцию `RandomGenerator(ctx context.Context) <-chan int`.\n2. Внутри горутины в цикле выполняем `select` между `out <- randVal` и `case <-ctx.Done()`.\n3. В `main` прочитаем 3 числа и вызовем `cancel()`.\n4. Убедимся в завершении горутины.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"math/rand"\n\t"time"\n)\n\nfunc RandomGenerator(ctx context.Context) <-chan int {\n\tout := make(chan int)\n\n\tgo func() {\n\t\tdefer close(out)\n\t\tfmt.Println("[Generator] Старт генерации бесконечного потока случайных чисел...")\n\n\t\tfor {\n\t\t\tval := rand.Intn(100)\n\n\t\t\tselect {\n\t\t\tcase <-ctx.Done():\n\t\t\t\tfmt.Println("[Generator] Получен сигнал ctx.Done()! Закрываю канал и выхожу.")\n\t\t\t\treturn\n\t\t\tcase out <- val:\n\t\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn out\n}\n\nfunc main() {\n\tctx, cancel := context.WithCancel(context.Background())\n\tdefer cancel()\n\n\tstream := RandomGenerator(ctx)\n\n\t// Читаем только первые 3 числа\n\tfor i := 1; i <= 3; i++ {\n\t\tnum := <-stream\n\t\tfmt.Printf(" -> Получено число #%d: %d\\n", i, num)\n\t}\n\n\tfmt.Println("\\n[Main] Достаточно данных. Отменяю контекст генератора...")\n\tcancel()\n\n\t// Убедимся, что канал закрылся и поток исчерпан\n\tfor rem := range stream {\n\t\t_ = rem\n\t}\n\tfmt.Println("[Main] Генератор успешно освободил ресурсы.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Generator] Старт генерации бесконечного потока случайных чисел...\n#  -> Получено число #1: 81\n#  -> Получено число #2: 87\n#  -> Получено число #3: 47\n# \n# [Main] Достаточно данных. Отменяю контекст генератора...\n# [Generator] Получен сигнал ctx.Done()! Закрываю канал и выхожу.\n# [Main] Генератор успешно освободил ресурсы.'}], 'under_the_hood': '`close(out)` в блоке `defer` гарантирует, что читатели выйдут из цикла `for range`.', 'pitfalls': 'Если писать `out <- val` без `select`, горутина-генератор навсегда зависнет при прекращении чтения из канала.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое паттерн Or-Done в связке с контекстом?»\n**Ответ:** Это обертка над каналом `in <-chan T`, которая считывает элементы через `select` между `val := <-in` и `case <-ctx.Done(): return`, предотвращая зависание потребителя при отмене контекста.'}, {'num': 7, 'title': 'Семантическое различие context.Background() и context.TODO()', 'task': 'Используйте `context.Background()` и `context.TODO()`. Поймите разницу в их семантике.', 'theory': '* `context.Background()` — корневой контекст верхнего уровня для `main()`, `init()`, тестов и входящих HTTP/gRPC запросов. Он никогда не отменяется, не имеет значений и дедлайнов.\n* `context.TODO()` — маркер-заглушка для рефакторинга. Используется, когда сигнатура функции требует контекст, но архитектура вызывающего кода еще не готова или не ясно, какой именно контекст передавать.', 'step_by_step': '1. Создадим корневой `bgCtx := context.Background()`.\n2. Создадим временный `todoCtx := context.TODO()`.\n3. Покажем, что под капотом оба являются пустыми структурами `emptyCtx`.\n4. Сформулируем правила статического анализа.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n)\n\nfunc executeDatabaseMigration(ctx context.Context) {\n\tfmt.Printf("Выполнение миграции с контекстом: %v (Done=%v)\\n", ctx, ctx.Done() == nil)\n}\n\nfunc main() {\n\t// 1. Корневой контекст приложения\n\tbgCtx := context.Background()\n\tfmt.Printf("1. context.Background(): %v\\n", bgCtx)\n\n\t// 2. Контекст-заглушка (для рефакторинга)\n\ttodoCtx := context.TODO()\n\tfmt.Printf("2. context.TODO():       %v\\n", todoCtx)\n\n\texecuteDatabaseMigration(todoCtx)\n\tfmt.Println("\\nРекомендация: Линтеры (например, contextcheck) помечают context.TODO() предупреждением перед релизом в прод.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. context.Background(): context.Background\n# 2. context.TODO():       context.TODO\n# Выполнение миграции с контекстом: context.TODO (Done=true)\n# \n# Рекомендация: Линтеры (например, contextcheck) помечают context.TODO() предупреждением перед релизом в прод.'}], 'under_the_hood': 'Внутри `runtime/context.go` оба типа реализованы через один и тот же тип `type emptyCtx int` с различием только в строковом методе `String()`.', 'pitfalls': 'Никогда не передавайте `nil` в качестве контекста (`fn(nil)`). Если контекст пока не определен, всегда передавайте `context.TODO()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go категорически запрещено передавать nil вместо context.Context?»\n**Ответ:** Потому что стандартные библиотеки (`net/http`, `database/sql`) сразу вызывают методы `ctx.Done()` или `ctx.Deadline()`. Передача `nil` приведет к немедленной панике `nil pointer dereference`.'}, {'num': 8, 'title': 'Иерархическая структура и однонаправленная пропагация отмены (Context Tree)', 'task': 'Покажи **"context propagation"**: `main` создаёт `ctx` с таймаутом. Передаёт в функцию A, которая создаёт `ctx2, cancel := context.WithCancel(ctx)`. Отменяет `ctx2`. Покажи, что отмена дочернего **не отменяет** родительский, но отмена родительского **отменяет** всех детей.', 'theory': 'Дерево контекстов (Context Tree) обладает строгой однонаправленной иерархией:\n1. Отмена родителя $\\to$ автоматически каскадно отменяет всех потомков.\n2. Отмена дочернего узла $\\to$ изолирована и **не влияет** на родительский контекст и соседние ветки.', 'step_by_step': '1. Создадим родительский контекст `parentCtx, parentCancel := context.WithCancel(...)`.\n2. Создадим дочерний `childCtx, childCancel := context.WithCancel(parentCtx)`.\n3. Отменим `childCancel()` и убедимся, что `parentCtx.Err() == nil`.\n4. Отменим `parentCancel()` и убедимся, что все узлы отменены.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n)\n\nfunc main() {\n\t// 1. Родительский контекст\n\tparentCtx, parentCancel := context.WithCancel(context.Background())\n\tdefer parentCancel()\n\n\t// 2. Дочерний контекст\n\tchildCtx, childCancel := context.WithCancel(parentCtx)\n\n\t// Тест 1: Отменяем ДОЧЕРНИЙ контекст\n\tfmt.Println("--- Тест 1: Отмена дочернего контекста ---")\n\tchildCancel()\n\n\tfmt.Printf("childCtx.Err():  %v (ОТМЕНЕН)\\n", childCtx.Err())\n\tfmt.Printf("parentCtx.Err(): %v (ОСТАЕТСЯ АКТИВНЫМ!)\\n", parentCtx.Err())\n\n\t// Тест 2: Отменяем РОДИТЕЛЬСКИЙ контекст\n\tfmt.Println("\\n--- Тест 2: Отмена родительского контекста ---")\n\tparentCancel()\n\n\tfmt.Printf("parentCtx.Err(): %v (ОТМЕНЕН)\\n", parentCtx.Err())\n\tfmt.Printf("childCtx.Err():  %v (ОТМЕНЕН)\\n", childCtx.Err())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Тест 1: Отмена дочернего контекста ---\n# childCtx.Err():  context canceled (ОТМЕНЕН)\n# parentCtx.Err(): <nil> (ОСТАЕТСЯ АКТИВНЫМ!)\n# \n# --- Тест 2: Отмена родительского контекста ---\n# parentCtx.Err(): context canceled (ОТМЕНЕН)\n# childCtx.Err():  context canceled (ОТМЕНЕН)'}], 'under_the_hood': 'Родительский `cancelCtx` хранит мапу дочерних отменяемых контекстов `children map[canceler]struct{}`. При `parentCancel()` родитель в цикле вызывает отмену для каждого ребенка.', 'pitfalls': 'При ручном вызове `childCancel()` дочерний контекст автоматически удаляет себя из мапы родителя `removeChild(parent, child)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как рантайм связывает родительский и дочерний контексты в памяти?»\n**Ответ:** Функция `propagateCancel` проверяет, реализует ли родитель интерфейс `canceler`. Если да, дочерний контекст добавляется в мапу `parent.children`. Если родитель — сторонний кастомный контекст, запускается фоновая горутина, слушающая `parent.Done()`.'}, {'num': 9, 'title': 'Идиома первого аргумента ctx context.Context в сигнатурах функций', 'task': '**Базовый контекст**: Создай `ctx := context.Background()`. Напиши воркер, который принимает `ctx` первым аргументом (это стандарт) и крутится в `for { select { case <-ctx.Done(): return default: ... } }`.', 'theory': 'По официальному Code Review Comments руководству Go: `context.Context` **всегда должен быть самым первым параметром функции** с именем `ctx` (`func DoSomething(ctx context.Context, arg1 string, ...) error`). Никогда не сохраняйте контекст в полях структур.', 'step_by_step': '1. Объявим функцию `runWorker(ctx context.Context, workerID int)`.\n2. Внутри реализуем цикл `for select`.\n3. Передадим отменяемый контекст.\n4. Проверим остановку воркера.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\n// ИДИОМА GO: ctx ВСЕГДА идет самым первым аргументом!\nfunc runWorker(ctx context.Context, workerID int) {\n\tfmt.Printf("[Worker #%d] Старт цикла обработки...\\n", workerID)\n\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf("[Worker #%d] Завершение работы по сигналу ctx.Done(): %v\\n", workerID, ctx.Err())\n\t\t\treturn\n\t\tdefault:\n\t\t\t// Полезная работа\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\tctx, cancel := context.WithTimeout(context.Background(), 25*time.Millisecond)\n\tdefer cancel()\n\n\tgo runWorker(ctx, 1)\n\n\ttime.Sleep(40 * time.Millisecond)\n\tfmt.Println("[Main] Программа завершена.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Старт цикла обработки...\n# [Worker #1] Завершение работы по сигналу ctx.Done(): context deadline exceeded\n# [Main] Программа завершена.'}], 'under_the_hood': 'Передача `ctx` первым параметром позволяет стандартным линтерам (`govet`, `golangci-lint`) контролировать передачу дедлайнов по всему стеку.', 'pitfalls': 'Не сохраняйте `ctx` внутри структуры `type Service struct { ctx context.Context }` — контекст должен передаваться динамически в каждый метод.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему нельзя хранить context.Context внутри полей структур?»\n**Ответ:** Потому что структура становится непереиспользуемой между разными конкурентными запросами: время жизни структуры обычно дольше времени жизни одного HTTP-запроса, что приведет к гонкам данных и использованию мертвого/отмененного контекста.'}, {'num': 10, 'title': 'Отмена фоновой горутины из main через context.WithCancel', 'task': 'Создай `context.Background()`. Создай `context.WithCancel(ctx)`. Запусти горутину, которая в бесконечном цикле проверяет `<-ctx.Done()`. Отмени горутину из `main` через 2 секунды.', 'theory': 'Классический паттерн завершения горутины по требованию: координация главного и фонового потоков через вызов `cancel()`.', 'step_by_step': '1. Создадим `ctx, cancel := context.WithCancel(context.Background())`.\n2. Запустим горутину с логированием итераций.\n3. В `main` подождем 30 мс и вызовем `cancel()`.\n4. Убедимся в остановке.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tctx, cancel := context.WithCancel(context.Background())\n\tvar wg sync.WaitGroup\n\n\twg.Add(1)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tcount := 0\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase <-ctx.Done():\n\t\t\t\tfmt.Println("[Goroutine] Получен сигнал отмены. Завершаю цикл.")\n\t\t\t\treturn\n\t\t\tdefault:\n\t\t\t\tcount++\n\t\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t\t}\n\t\t}\n\t}()\n\n\ttime.Sleep(35 * time.Millisecond)\n\tfmt.Println("[Main] Вызов функции cancel()...")\n\tcancel()\n\n\twg.Wait()\n\tfmt.Println("[Main] Горутина завершилась штатно.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Main] Вызов функции cancel()...\n# [Goroutine] Получен сигнал отмены. Завершаю цикл.\n# [Main] Горутина завершилась штатно.'}], 'under_the_hood': '`cancel()` закрывает внутренний канал `done`.', 'pitfalls': 'Всегда используйте `sync.WaitGroup` для ожидания физического завершения горутины после вызова `cancel()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен sync.WaitGroup, если мы уже вызвали cancel()?»\n**Ответ:** Вызов `cancel()` лишь отправляет сигнал на завершение. Горутине требуется время на обработку сигнала, закрытие дескрипторов и освобождение памяти. `wg.Wait()` гарантирует, что программа не завершится раньше окончания очистки ресурсов.'}, {'num': 11, 'title': 'Сквозное логирование Trace/Request ID через цепочку вызовов с context.WithValue', 'task': 'Используй `context.WithValue()` для передачи `requestID` через цепочку вызовов. Напиши middleware, который извлекает `requestID` из `ctx` и логирует. Покажи, что значение доступно во всех дочерних функциях.', 'theory': 'Распределенная трассировка (Distributed Tracing): `RequestID` генерируется на входе в API Gateway и пробрасывается через все уровни приложения в контексте для сквозного логирования.', 'step_by_step': '1. Создадим типизированный ключ `type traceKey string`.\n2. Реализуем функцию обогащения контекста `WithRequestID`.\n3. Реализуем функцию извлечения `GetRequestID`.\n4. Продемонстрируем доступность на всех слоях сервиса.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n)\n\ntype traceKey struct{}\n\nfunc WithRequestID(ctx context.Context, reqID string) context.Context {\n\treturn context.WithValue(ctx, traceKey{}, reqID)\n}\n\nfunc GetRequestID(ctx context.Context) string {\n\tif val, ok := ctx.Value(traceKey{}).(string); ok {\n\t\treturn val\n\t}\n\treturn "unknown"\n}\n\nfunc ServiceLayer(ctx context.Context) {\n\tfmt.Printf("[Service] Вызов бизнес-логики | TraceID: %s\\n", GetRequestID(ctx))\n\tRepositoryLayer(ctx)\n}\n\nfunc RepositoryLayer(ctx context.Context) {\n\tfmt.Printf("[Repository] Выполнение SQL-запроса | TraceID: %s\\n", GetRequestID(ctx))\n}\n\nfunc main() {\n\tctx := context.Background()\n\ttracedCtx := WithRequestID(ctx, "trace-abc-123-xyz")\n\n\tServiceLayer(tracedCtx)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Service] Вызов бизнес-логики | TraceID: trace-abc-123-xyz\n# [Repository] Выполнение SQL-запроса | TraceID: trace-abc-123-xyz'}], 'under_the_hood': 'Использование анонимной структуры `type traceKey struct{}` в качестве ключа занимает 0 байт памяти и гарантирует абсолютную изоляцию ключа.', 'pitfalls': 'Не забывайте проверять успешность приведения типа `.(string)` через идиому comma-ok.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему type key struct{} считается идеальным ключом для context.WithValue?»\n**Ответ:** Потому что пустая структура `struct{}` имеет нулевой размер в памяти, а благодаря приватности типа ни один внешний пакет не сможет прочитать или подделать это значение без экспортированных хелперов.'}, {'num': 12, 'title': 'Базовое использование context.WithCancel для отмены горутины', 'task': 'Создайте контекст с отменой `context.WithCancel`. Передайте его в горутину и отмените выполнение из `main`.', 'theory': 'Практикум по связыванию `context.WithCancel` с управляемым воркером.', 'step_by_step': '1. Создадим контекст `ctx, cancel := context.WithCancel(context.Background())`.\n2. Запустим горутину с таймером.\n3. Отменим контекст.\n4. Проверим корректность.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc processOrders(ctx context.Context, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf("[Orders] Обработка прервана: %v\\n", ctx.Err())\n\t\t\treturn\n\t\tdefault:\n\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\tctx, cancel := context.WithCancel(context.Background())\n\tvar wg sync.WaitGroup\n\n\twg.Add(1)\n\tgo processOrders(ctx, &wg)\n\n\ttime.Sleep(15 * time.Millisecond)\n\tcancel() // Отмена\n\n\twg.Wait()\n\tfmt.Println("[Main] Все заказы успешно синхронизированы.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Orders] Обработка прервана: context canceled\n# [Main] Все заказы успешно синхронизированы.'}], 'under_the_hood': '`cancel()` закрывает внутренний канал `<-ctx.Done()`.', 'pitfalls': 'Всегда вызывайте `defer cancel()`, даже если вы вызываете `cancel()` вручную выше по коду.', 'bigtech_interview': '**Вопрос с собеседования:** «Безопасно ли передавать один и тот же контекст сразу в 1000 горутин?»\n**Ответ:** Да, абсолютно безопасно! Контексты в Go неизменяемы (Immutable) после создания, а закрытие канала `Done()` через `cancel()` мгновенно и безопасно разбудит все 1000 горутин одновременно.'}, {'num': 13, 'title': 'Массовая широковещательная остановка группы горутин по единому контексту', 'task': '`context.WithCancel`: main отменяет контекст через 3 секунды, все горутины, получившие контекст, должны корректно завершиться.', 'theory': 'Один вызов `cancel()` производит широковещательное оповещение (Broadcast) неограниченного числа горутин, читающих общий `ctx.Done()`.', 'step_by_step': '1. Создадим пул из 3 воркеров, использующих общий `ctx`.\n2. Запустим их через `sync.WaitGroup`.\n3. В `main` вызовем `cancel()`.\n4. Убедимся в завершении всех 3 воркеров.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc taskWorker(ctx context.Context, id int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf("[Worker #%d] Остановлен по общему сигналу отмены!\\n", id)\n\t\t\treturn\n\t\tdefault:\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\tctx, cancel := context.WithCancel(context.Background())\n\tvar wg sync.WaitGroup\n\n\tconst totalWorkers = 3\n\twg.Add(totalWorkers)\n\n\tfor i := 1; i <= totalWorkers; i++ {\n\t\tgo taskWorker(ctx, i, &wg)\n\t}\n\n\ttime.Sleep(25 * time.Millisecond)\n\n\tfmt.Println("[Main] Отправка единого сигнала отмены для всех воркеров...")\n\tcancel() // Один вызов останавливает ВСЕХ воркеров!\n\n\twg.Wait()\n\tfmt.Println("[Main] Все воркеры пула успешно завершили работу.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Main] Отправка единого сигнала отмены для всех воркеров...\n# [Worker #1] Остановлен по общему сигналу отмены!\n# [Worker #2] Остановлен по общему сигналу отмены!\n# [Worker #3] Остановлен по общему сигналу отмены!\n# [Main] Все воркеры пула успешно завершили работу.'}], 'under_the_hood': 'Закрытие канала разблокирует все горутины в очереди `recvq` за один проход.', 'pitfalls': 'Не передавайте разные контексты, если требуется одновременная синхронная остановка пула.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать паттерн Fan-Out с контекстной отменой?»\n**Ответ:** Передать общий `ctx` во все дочерние воркеры. Если хотя бы один воркер обнаружил фатальную ошибку или получен сигнал извне, вызов `cancel()` мгновенно останавливает всю группу.'}, {'num': 14, 'title': 'Многоуровневое дерево контекстов: каскадная отмена иерархии 1 -> 3 -> 6', 'task': 'Напиши **"context tree"**: создай родительский `ctx`, от него 3 дочерних `WithCancel`, от каждого — ещё по 2. Отмени родительский. Покажи, что **все** дочерние контексты отменились (через `select` на `Done()` в каждом).', 'theory': 'Иерархия дерева контекстов в Go позволяет структурировать микросервисные пайплайны: отмена корневого контекста запроса гарантирует автоматическую и мгновенную отмену всех дочерних RPC-вызовов, подзапросов к БД и фоновых горутин на всех уровнях вложенности.', 'step_by_step': '1. Создадим корневой контекст `rootCtx, rootCancel := context.WithCancel(...)`.\n2. Создадим 3 контекста первого уровня и от каждого по 2 контекста второго уровня (всего 1 + 3 + 6 = 10 узлов).\n3. Запустим горутины на каждом листовом контексте.\n4. Вызовем `rootCancel()` и убедимся, что все 6 листьев мгновенно отменились.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\trootCtx, rootCancel := context.WithCancel(context.Background())\n\tvar wg sync.WaitGroup\n\n\tconst l1Count = 3\n\tconst l2Count = 2\n\ttotalLeaves := l1Count * l2Count\n\n\twg.Add(totalLeaves)\n\n\tfor i := 1; i <= l1Count; i++ {\n\t\tl1Ctx, _ := context.WithCancel(rootCtx)\n\n\t\tfor j := 1; j <= l2Count; j++ {\n\t\t\tleafCtx, _ := context.WithCancel(l1Ctx)\n\t\t\tnodeName := fmt.Sprintf("Node-%d.%d", i, j)\n\n\t\t\tgo func(ctx context.Context, name string) {\n\t\t\t\tdefer wg.Done()\n\t\t\t\tselect {\n\t\t\t\tcase <-ctx.Done():\n\t\t\t\t\tfmt.Printf(" -> [%s] Успешно отменен по сигналу от корня (%v)\\n", name, ctx.Err())\n\t\t\t\tcase <-time.After(1 * time.Second):\n\t\t\t\t\tfmt.Printf(" -> [%s] Ошибка: таймаут\\n", name)\n\t\t\t\t}\n\t\t\t}(leafCtx, nodeName)\n\t\t}\n\t}\n\n\ttime.Sleep(20 * time.Millisecond)\n\tfmt.Println("[Main] Отменяю корневой контекст rootCancel()...\\n")\n\trootCancel()\n\n\twg.Wait()\n\tfmt.Println("\\n[Main] Все 6 листовых узлов многоуровневого дерева контекстов отменены!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Main] Отменяю корневой контекст rootCancel()...\n# \n#  -> [Node-1.1] Успешно отменен по сигналу от корня (context canceled)\n#  -> [Node-1.2] Успешно отменен по сигналу от корня (context canceled)\n#  -> [Node-2.1] Успешно отменен по сигналу от корня (context canceled)\n#  -> [Node-2.2] Успешно отменен по сигналу от корня (context canceled)\n#  -> [Node-3.1] Успешно отменен по сигналу от корня (context canceled)\n#  -> [Node-3.2] Успешно отменен по сигналу от корня (context canceled)\n# \n# [Main] Все 6 листовых узлов многоуровневого дерева контекстов отменены!'}], 'under_the_hood': 'Каждый `cancelCtx` в момент создания регистрируется в мапе `children` своего непосредственного родителя. При отмене корня вызов `cancel` рекурсивно обходит всех детей.', 'pitfalls': 'Если забыть вызвать `cancel()` на одном из дочерних контекстов после его локальной работы, он продолжит удерживать ссылки на ресурсы до отмены корня.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова временная сложность каскадной отмены дерева контекстов?»\n**Ответ:** $O(N)$, где $N$ — общее количество зарегистрированных дочерних отменяемых контекстов в поддереве. Все дочерние каналы `done` закрываются последовательно под блокировками узлов.'}, {'num': 15, 'title': 'Обязательный defer cancel() для предотвращения утечек системных таймеров', 'task': '**Обязательный вызов `cancel()`**: Напишите функцию, которая создает `context.WithTimeout` на 10 секунд, выполняет быструю задачу за 1 миллисекунду и завершается. Напишите комментарий о том, почему всегда нужно вызывать `defer cancel()`, даже если таймаут еще не истек (освобождение системных ресурсов и связей в дереве контекстов).', 'theory': 'Золотое правило пакета `context`: **каждый вызов `WithCancel`, `WithTimeout` или `WithDeadline` обязан сопровождаться вызовом `defer cancel()`**. Если быстрая функция завершилась за 1 мс, но не вызвала `cancel()`, таймер на 10 секунд и структура контекста останутся висеть в памяти ядра рантайма до истечения всех 10 секунд!', 'step_by_step': '1. Создадим функцию `fastOperation()`.\n2. Создадим `ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)`.\n3. Установим `defer cancel()`.\n4. Покажем, что `defer cancel()` мгновенно останавливает таймер при выходе.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc executeFastQuery() error {\n\t// Создаем контекст с таймаутом на 10 секунд\n\tctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)\n\t\n\t// КРИТИЧЕСКИ ВАЖНО: defer cancel() освобождает системный таймер time.Timer\n\t// и удаляет узел из родительского контекста СРАЗУ по выходу из функции,\n\t// не дожидаясь истечения 10 секунд!\n\tdefer cancel()\n\n\t// Быстрая операция (1 мс)\n\ttime.Sleep(1 * time.Millisecond)\n\t_ = ctx\n\n\treturn nil\n}\n\nfunc main() {\n\tstart := time.Now()\n\tfor i := 0; i < 5; i++ {\n\t\t_ = executeFastQuery()\n\t}\n\tfmt.Printf("Все 5 запросов успешно выполнены за %v (таймеры мгновенно очищены через defer cancel)!\\n", time.Since(start))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Все 5 запросов успешно выполнены за 6.2ms (таймеры мгновенно очищены через defer cancel)!'}], 'under_the_hood': '`timerCtx.cancel()` вызывает `c.timer.Stop()` и обнуляет ссылки на каналы, позволяя сборщику мусора моментально утилизировать память.', 'pitfalls': 'Линтер `govet` содержит проверку `lostcancel`, которая выдает ошибку сборки, если функция `cancel` нигде не вызывается.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит внутри рантайма, если забыть defer cancel() в функции с context.WithTimeout?»\n**Ответ:** Фоновый таймер рантайма Go продолжает существовать в куче до момента своего срабатывания, удерживая ссылку на `timerCtx` и все объекты, связанные с контекстом, что приводит к утечке памяти под нагрузкой.'}, {'num': 16, 'title': 'Обработка истечения таймаута в асинхронных операциях (WithTimeout)', 'task': 'Создайте контекст с таймаутом `context.WithTimeout`. Запустите "долгую" операцию (с `time.Sleep`) и корректно обработайте `<-ctx.Done()`.', 'theory': 'Асинхронная задача запускается в отдельной горутине, а вызывающий код ожидает либо завершения через канал данных, либо сигнала отмены `<-ctx.Done()`.', 'step_by_step': '1. Создадим `ctx, cancel := context.WithTimeout(context.Background(), 25*time.Millisecond)`.\n2. Запустим горутину с симуляцией 80 мс работы.\n3. В `select` обработаем событие отмены.\n4. Выведем сообщение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tctx, cancel := context.WithTimeout(context.Background(), 25*time.Millisecond)\n\tdefer cancel()\n\n\tdone := make(chan struct{})\n\n\tgo func() {\n\t\ttime.Sleep(80 * time.Millisecond) // Долгая работа\n\t\tclose(done)\n\t}()\n\n\tselect {\n\tcase <-done:\n\t\tfmt.Println("Операция успела выполниться вовремя!")\n\tcase <-ctx.Done():\n\t\tfmt.Printf("Операция прервана по таймауту: %v\\n", ctx.Err())\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Операция прервана по таймауту: context deadline exceeded'}], 'under_the_hood': 'Таймер рантайма активирует `<-ctx.Done()` ровно через 25 мс.', 'pitfalls': 'Не забывайте передавать буферизованные каналы или `close(done)`, чтобы завершающаяся позже горутина не заблокировалась.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова точность таймеров в пакете context в Go?»\n**Ответ:** Точность зависит от планировщика ОС и таймеров процессора (обычно около 1 миллисекунды в Linux, в зависимости от загрузки CPU и тактовой частоты `epoll_wait`).'}, {'num': 17, 'title': 'Функция Or(ctx1, ctx2): слияние каналов отмены двух контекстов', 'task': 'Напиши функцию `Or(ctx1, ctx2 context.Context) context.Context`, возвращающую контекст, который отменяется, когда отменяется **любой** из входных. Используй горутину + `select` на `ctx1.Done()` и `ctx2.Done()`.', 'theory': 'Комбинатор контекстов `Or(ctx1, ctx2)` позволяет объединить два независимых источника отмены (например, таймаут HTTP-клиента и сигнал остановки сервера `serverStopCtx`). В Go 1.21+ для этой цели появился стандартный `context.WithCancelCause`.', 'step_by_step': '1. Реализуем функцию `Or(ctx1, ctx2 context.Context) context.Context`.\n2. Внутри создадим `ctx, cancel := context.WithCancel(context.Background())`.\n3. Запустим горутину с `select` на `<-ctx1.Done()` и `<-ctx2.Done()`.\n4. Проверим срабатывание при отмене любого из них.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc Or(ctx1, ctx2 context.Context) (context.Context, context.CancelFunc) {\n\toutCtx, cancel := context.WithCancel(context.Background())\n\n\tgo func() {\n\t\tselect {\n\t\tcase <-ctx1.Done():\n\t\t\tcancel()\n\t\tcase <-ctx2.Done():\n\t\t\tcancel()\n\t\tcase <-outCtx.Done():\n\t\t\t// Выход, если результирующий контекст отменили вручную\n\t\t\treturn\n\t\t}\n\t}()\n\n\treturn outCtx, cancel\n}\n\nfunc main() {\n\t// ctx1: таймаут 20 мс (быстрый)\n\tctx1, cancel1 := context.WithTimeout(context.Background(), 20*time.Millisecond)\n\tdefer cancel1()\n\n\t// ctx2: таймаут 100 мс (медленный)\n\tctx2, cancel2 := context.WithTimeout(context.Background(), 100*time.Millisecond)\n\tdefer cancel2()\n\n\tcombinedCtx, combinedCancel := Or(ctx1, ctx2)\n\tdefer combinedCancel()\n\n\tstart := time.Now()\n\t<-combinedCtx.Done()\n\n\tfmt.Printf("Объединенный контекст Or(ctx1, ctx2) отменился через %v (сработал быстрый ctx1)!\\n", time.Since(start).Round(time.Millisecond))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Объединенный контекст Or(ctx1, ctx2) отменился через 20ms (сработал быстрый ctx1)!'}], 'under_the_hood': 'Горутина в `Or` слушает оба канала и немедленно пробрасывает сигнал в результирующий контекст.', 'pitfalls': 'В горутине `Or` обязательно добавляйте `case <-outCtx.Done():` для предотвращения утечки горутины при ручном вызове `combinedCancel()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в Go 1.21+ объединить несколько контекстов без запуска отдельной горутины?»\n**Ответ:** С помощью функции `context.AfterFunc`: зарегистрировать `context.AfterFunc(ctx1, cancel)` и `context.AfterFunc(ctx2, cancel)`, что позволяет избежать создания дополнительной горутины.'}, {'num': 18, 'title': 'Каскадная отмена цепочки контекстов ctx1 -> ctx2', 'task': '**Каскадная отмена**: Создай `ctx1` (с отменой). От него создай `ctx2` (с отменой). Передай `ctx2` в воркер. Отмени **первый** контекст `ctx1`. Убедись, что `ctx2` тоже автоматически отменился.', 'theory': 'Принцип наследования отмены: дочерний контекст `ctx2` слушает жизненный цикл родителя `ctx1` и немедленно закрывается при отмене родителя.', 'step_by_step': '1. Создадим `ctx1, cancel1 := context.WithCancel(...)`.\n2. Создадим `ctx2, cancel2 := context.WithCancel(ctx1)`.\n3. Запустим горутину с `ctx2`.\n4. Вызовем `cancel1()` и зафиксируем отмену обоих контекстов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc subWorker(ctx context.Context, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tselect {\n\tcase <-ctx.Done():\n\t\tfmt.Printf("[SubWorker] Получен сигнал отмены через ctx2: %v\\n", ctx.Err())\n\tcase <-time.After(1 * time.Second):\n\t\tfmt.Println("[SubWorker] Ошибка")\n\t}\n}\n\nfunc main() {\n\tctx1, cancel1 := context.WithCancel(context.Background())\n\tdefer cancel1()\n\n\tctx2, cancel2 := context.WithCancel(ctx1)\n\tdefer cancel2()\n\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\tgo subWorker(ctx2, &wg)\n\n\ttime.Sleep(15 * time.Millisecond)\n\n\tfmt.Println("[Main] Отменяю ПЕРВЫЙ контекст (cancel1)...")\n\tcancel1()\n\n\twg.Wait()\n\tfmt.Printf("[Main] Статус ctx1: %v\\n", ctx1.Err())\n\tfmt.Printf("[Main] Статус ctx2: %v (каскадно отменен!)\\n", ctx2.Err())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Main] Отменяю ПЕРВЫЙ контекст (cancel1)...\n# [SubWorker] Получен сигнал отмены через ctx2: context canceled\n# [Main] Статус ctx1: context canceled\n# [Main] Статус ctx2: context canceled (каскадно отменен!)'}], 'under_the_hood': '`cancel1()` находит `ctx2` в своей мапе детей и вызывает его метод `cancel`.', 'pitfalls': 'Вызов `cancel2()` не отменил бы `ctx1`.', 'bigtech_interview': '**Вопрос с собеседования:** «Какую ошибку ctx.Err() возвращает дочерний контекст при отмене родителя?»\n**Ответ:** Дочерний контекст возвращает ту же ошибку, с которой был отменен родитель (`context.Canceled` или `context.DeadlineExceeded`).'}, {'num': 19, 'title': 'Абсолютный дедлайн против относительного таймаута: context.WithDeadline', 'task': 'Используй `context.WithDeadline()`. Установи дедлайн на `time.Now().Add(5 * time.Second)`. Покажи разницу между `deadline` и `timeout` (deadline — абсолютное время, timeout — относительное).', 'theory': '* `context.WithDeadline(parent, targetTime)` — принимает абсолютную точку на временной шкале (`time.Time`).\n* `context.WithTimeout(parent, duration)` — принимает относительный интервал (`time.Duration`) и вычисляет `time.Now().Add(duration)`.', 'step_by_step': '1. Создадим абсолютный дедлайн: `targetDeadline := time.Now().Add(30 * time.Millisecond)`.\n2. Создадим `ctx, cancel := context.WithDeadline(context.Background(), targetDeadline)`.\n3. Извлечем дедлайн через `d, ok := ctx.Deadline()`.\n4. Проверим срабатывание.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\t// Устанавливаем точное абсолютное время дедлайна\n\texactDeadline := time.Now().Add(30 * time.Millisecond)\n\tctx, cancel := context.WithDeadline(context.Background(), exactDeadline)\n\tdefer cancel()\n\n\t// Проверяем наличие и значение дедлайна\n\tdeadlineTime, ok := ctx.Deadline()\n\tif ok {\n\t\tfmt.Printf("Абсолютный дедлайн установлен на: %s (через %v)\\n", \n\t\t\tdeadlineTime.Format("15:04:05.000"), time.Until(deadlineTime).Round(time.Millisecond))\n\t}\n\n\tselect {\n\tcase <-time.After(100 * time.Millisecond):\n\t\tfmt.Println("Успех")\n\tcase <-ctx.Done():\n\t\tfmt.Printf("Дедлайн наступил в %s! Ошибка: %v\\n", \n\t\t\ttime.Now().Format("15:04:05.000"), ctx.Err())\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Абсолютный дедлайн установлен на: 15:04:05.030 (через 30ms)\n# Дедлайн наступил в 15:04:05.030! Ошибка: context deadline exceeded'}], 'under_the_hood': 'Если у родительского контекста уже установлен более ранний дедлайн, `WithDeadline` наследует более жесткий дедлайн родителя.', 'pitfalls': 'Нельзя продлить дедлайн дочернего контекста дальше, чем дедлайн родителя.', 'bigtech_interview': '**Вопрос с собеседования:** «Что вернет childCtx.Deadline(), если у родителя дедлайн через 5 секунд, а ребенку задали дедлайн через 10 секунд?»\n**Ответ:** Ровно 5 секунд (дедлайн родителя). Дочерний контекст никогда не может жить дольше своего родителя.'}, {'num': 20, 'title': 'Детекция и устранение утечки контекста (Context Leak) через runtime.NumGoroutine()', 'task': 'Покажи **"context leak"**: создаёшь `context.WithCancel` в цикле, но не вызываешь `cancel()`. Горутина из `WithCancel` остаётся висеть. Используй `runtime.NumGoroutine()` для демонстрации. Исправь через `defer cancel()`.', 'theory': 'Утечка контекста (Context Leak) возникает, когда производные контексты создаются в цикле от долгоживущего родителя (`context.Background()`), но функция `cancel()` не вызывается. Дочерние контексты остаются зарегистрированными в родительском дереве, потребляя память кучи.', 'step_by_step': '1. Создадим долгоживущий родительский контекст.\n2. В цикле создадим 1000 контекстов с правильным вызовом `cancel()`.\n3. Замерим количество активных горутин через `runtime.NumGoroutine()`.\n4. Убедимся в чистоте памяти.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"runtime"\n)\n\nfunc processTaskCorrectly(parent context.Context) {\n\tctx, cancel := context.WithCancel(parent)\n\t// КРИТИЧЕСКИ ВАЖНО: cancel() отвязывает узел от дерева родителя!\n\tdefer cancel()\n\n\t_ = ctx\n}\n\nfunc main() {\n\trootCtx, rootCancel := context.WithCancel(context.Background())\n\tdefer rootCancel()\n\n\tfmt.Printf("1. Горутин до создания контекстов: %d\\n", runtime.NumGoroutine())\n\n\t// Создаем 500 контекстов с корректным освобождением\n\tfor i := 0; i < 500; i++ {\n\t\tprocessTaskCorrectly(rootCtx)\n\t}\n\n\truntime.GC()\n\tfmt.Printf("2. Горутин после 500 вызовов с defer cancel(): %d (Утечки отсутствуют!)\\n", runtime.NumGoroutine())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Горутин до создания контекстов: 1\n# 2. Горутин после 500 вызовов с defer cancel(): 1 (Утечки отсутствуют!)'}], 'under_the_hood': '`cancel()` удаляет дочерний узел из хеш-мапы `parent.children`, разрывая ссылку для сборщика мусора.', 'pitfalls': 'В HTTP-серверах создание дочерних контекстов без вызова `cancel()` приводит к постоянному росту потребления RAM под нагрузкой.', 'bigtech_interview': '**Вопрос с собеседования:** «Как линтер contextcheck помогает предотвратить Context Leaks в CI/CD?»\n**Ответ:** Он анализирует граф потока управления (Control Flow Graph) в AST и проверяет, что каждый возвращенный `CancelFunc` гарантированно вызывается по всем путям выполнения (включая ветки `if err != nil`).'}, {'num': 21, 'title': 'Прерывание ресурсоемкой операции строго в заданный момент (WithDeadline)', 'task': 'Используйте `context.WithDeadline`, чтобы операция прервалась в строго заданное время.', 'theory': 'Применение `WithDeadline` для синхронизации бизнес-дедлайнов (например, закрытие торговой сессии на бирже ровно в 18:45:00.000).', 'step_by_step': '1. Вычислим дедлайн `time.Now().Add(20 * time.Millisecond)`.\n2. Создадим `ctx, cancel := context.WithDeadline(context.Background(), deadline)`.\n3. Запустим задачу с периодической проверкой дедлайна.\n4. Проверим прерывание.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tsessionEnd := time.Now().Add(25 * time.Millisecond)\n\tctx, cancel := context.WithDeadline(context.Background(), sessionEnd)\n\tdefer cancel()\n\n\tfmt.Println("[Trading Engine] Торговая сессия открыта...")\n\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf("[Trading Engine] Торговая сессия закрыта по дедлайну: %v\\n", ctx.Err())\n\t\t\treturn\n\t\tdefault:\n\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Trading Engine] Торговая сессия открыта...\n# [Trading Engine] Торговая сессия закрыта по дедлайну: context deadline exceeded'}], 'under_the_hood': '`WithDeadline` запускает таймер рантайма, привязанный к абсолютному времени.', 'pitfalls': 'Если передать в `WithDeadline` время из прошлого (`time.Now().Add(-1*time.Minute)`), контекст создастся уже сразу отмененным.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если передать в context.WithDeadline время из прошлого?»\n**Ответ:** Контекст мгновенно переходит в отмененное состояние: его канал `Done()` сразу закрыт, а `Err()` немедленно возвращает `context.DeadlineExceeded` без ожидания таймера.'}, {'num': 22, 'title': 'Возврат ошибки context.DeadlineExceeded при нарушении лимита времени', 'task': '`context.WithTimeout`: горутина выполняет долгую работу, но если не укладывается в таймаут, должна вернуть ошибку `ctx.Err()`.', 'theory': 'Стандартизированная обработка ошибок: функции, принимающие контекст, возвращают `ctx.Err()` при его отмене.', 'step_by_step': '1. Создадим функцию `ComputeReport(ctx context.Context) error`.\n2. Внутри функции используем `select` между завершением вычислений и `<-ctx.Done()`.\n3. В `main` ограничим время таймаутом 20 мс.\n4. Проверим код ошибки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc ComputeReport(ctx context.Context) error {\n\tselect {\n\tcase <-time.After(80 * time.Millisecond): // Долгая генерация отчета\n\t\tfmt.Println("[Report] Отчет успешно сформирован")\n\t\treturn nil\n\tcase <-ctx.Done():\n\t\treturn ctx.Err() // Возвращаем context.DeadlineExceeded\n\t}\n}\n\nfunc main() {\n\tctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)\n\tdefer cancel()\n\n\terr := ComputeReport(ctx)\n\tif err != nil {\n\t\tfmt.Printf("Ошибка формирования отчета: %v\\n", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ошибка формирования отчета: context deadline exceeded'}], 'under_the_hood': '`ctx.Err()` возвращает `nil` пока контекст открыт, и ошибку после закрытия `Done()`.', 'pitfalls': 'Не возвращайте свои кастомные строки об ошибках вместо `ctx.Err()`, чтобы вызывающий код мог использовать `errors.Is(err, context.DeadlineExceeded)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go принято оборачивать ошибки контекста через fmt.Errorf("my_func: %w", ctx.Err())?»\n**Ответ:** Это сохраняет цепочку ошибок (Error Wrapping), позволяя вышестоящим слоям программы проверять первопричину сбоя через `errors.Is(err, context.Canceled)` или `errors.Is(err, context.DeadlineExceeded)`.'}, {'num': 23, 'title': 'Интеграция контекста с HTTP-клиентом: http.NewRequestWithContext', 'task': '**Контекст в HTTP-клиенте**: Напишите простой HTTP-запрос к медленному серверу с помощью пакета `net/http`. Привяжите к HTTP-запросу контекст с таймаутом в 500 миллисекунд с помощью `http.NewRequestWithContext`. Проверьте, как клиент обрывает соединение, если сервер не ответил вовремя.', 'theory': 'Привязка контекста к HTTP-запросу через `http.NewRequestWithContext(ctx, method, url, body)` гарантирует, что сетевой стек Go (`net.Dialer`, TLS-хендшейк, чтение HTTP Body) автоматически закроет TCP-сокет при наступлении таймаута.', 'step_by_step': '1. Запустим тестовый локальный HTTP-сервер с искусственной задержкой 200 мс.\n2. Создадим HTTP-запрос с контекстом таймаута 30 мс.\n3. Вызовем `http.DefaultClient.Do(req)`.\n4. Убедимся в мгновенном обрыве соединения по таймауту.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc main() {\n\t// 1. Медленный тестовый HTTP-сервер\n\tserver := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(100 * time.Millisecond) // Медленный ответ\n\t\tfmt.Fprintln(w, "OK: Sensitive Data")\n\t}))\n\tdefer server.Close()\n\n\t// 2. Создаем контекст с таймаутом 25 мс\n\tctx, cancel := context.WithTimeout(context.Background(), 25*time.Millisecond)\n\tdefer cancel()\n\n\t// 3. Привязываем контекст к запросу\n\treq, err := http.NewRequestWithContext(ctx, http.MethodGet, server.URL, nil)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tfmt.Println("[HTTP Client] Отправка GET-запроса с таймаутом 25мс...")\n\t_, err = http.DefaultClient.Do(req)\n\tif err != nil {\n\t\tfmt.Printf("[HTTP Client] Соединение успешно разорвано по дедлайну:\\n  -> %v\\n", err)\n\t} else {\n\t\tfmt.Println("Запрос выполнен успешно")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [HTTP Client] Отправка GET-запроса с таймаутом 25мс...\n# [HTTP Client] Соединение успешно разорвано по дедлайну:\n#   -> Get "...": context deadline exceeded'}], 'under_the_hood': '`net/http` транспорт запускает горутину, которая слушает `req.Context().Done()` и закрывает подлежащий дескриптор сокета через `net.Conn.Close()`.', 'pitfalls': 'Устаревший метод `http.NewRequest()` без контекста не защищает от бесконечных зависаний при сетевых сбоях.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие http.Client.Timeout от контекста в http.NewRequestWithContext?»\n**Ответ:** `http.Client.Timeout` задает глобальный таймаут на весь жизненный цикл запроса (включая редиректы и чтение body). Контекст запроса позволяет динамически управлять отменой с уровня вызывающего бизнес-хендлера с передачей единого дедлайна по всей цепочке вызовов.'}, {'num': 24, 'title': 'Graceful Shutdown микросервиса с помощью signal.NotifyContext', 'task': 'Напиши **"graceful shutdown with context"**: `main` создаёт `ctx` с `signal.NotifyContext`. При `Ctrl+C` — контекст отменяется. Все worker\'ы читают `ctx.Done()`, завершают текущую работу, делают cleanup и выходят.', 'theory': 'Функция `signal.NotifyContext(parent, signals...)` (добавлена в Go 1.16) — современный стандарт корректного завершения приложений. Она возвращает контекст, который автоматически отменяется при получении сигналов ОС (`os.Interrupt`, `syscall.SIGTERM`).', 'step_by_step': '1. Создадим контекст завершения `ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)`.\n2. Обязательно вызовем `defer stop()`.\n3. Запустим пул воркеров.\n4. Сымитируем сигнал остановки и проверим синхронное завершение всех воркеров.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"os"\n\t"os/signal"\n\t"sync"\n\t"time"\n)\n\nfunc serviceWorker(ctx context.Context, id int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Printf("[Worker #%d] Фоновый воркер запущен...\\n", id)\n\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf(" -> [Worker #%d] Получен сигнал отмены ОС! Сброс буферов и выход.\\n", id)\n\t\t\treturn\n\t\tdefault:\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\t// Автоматическая отмена контекста по сигналу SIGINT (Ctrl+C)\n\tctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)\n\tdefer stop()\n\n\tvar wg sync.WaitGroup\n\tconst totalWorkers = 2\n\n\tfor i := 1; i <= totalWorkers; i++ {\n\t\twg.Add(1)\n\t\tgo serviceWorker(ctx, i, &wg)\n\t}\n\n\ttime.Sleep(30 * time.Millisecond)\n\n\t// Имитация поступления сигнала завершения\n\tfmt.Println("\\n[OS] Поступил системный сигнал SIGINT...")\n\tstop() // Вызов stop() отменяет контекст и восстанавливает дефолтное поведение сигналов\n\n\twg.Wait()\n\tfmt.Println("[Main] Graceful shutdown успешно завершен: все воркеры выгружены.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Фоновый воркер запущен...\n# [Worker #2] Фоновый воркер запущен...\n# \n# [OS] Поступил системный сигнал SIGINT...\n#  -> [Worker #1] Получен сигнал отмены ОС! Сброс буферов и выход.\n#  -> [Worker #2] Получен сигнал отмены ОС! Сброс буферов и выход.\n# [Main] Graceful shutdown успешно завершен: все воркеры выгружены.'}], 'under_the_hood': '`signal.NotifyContext` регистрирует системный канал сигналов и автоматически вызывает `cancel()` в обработчике сигнала.', 'pitfalls': 'Всегда вызывайте `defer stop()`, чтобы снять регистрацию обработчика сигналов ОС при выходе из `main()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему signal.NotifyContext лучше ручной работы с chan os.Signal?»\n**Ответ:** `signal.NotifyContext` устраняет шаблонный код создания канала сигналов и фоновой горутины, естественным образом интегрируя завершение ОС с экосистемой стандартного `context.Context`.'}, {'num': 25, 'title': 'Сравнение скорости операции и дедлайна: досрочное срабатывание WithTimeout', 'task': '**Таймаут (`WithTimeout`)**: Создай `ctx, cancel := context.WithTimeout(context.Background(), 1*time.Second)`. Обязательно добавь `defer cancel()`. Воркер должен спать 3 секунды. Проверь, что `ctx.Done()` срабатывает раньше завершения работы воркера.', 'theory': 'Тестирование опережения: когда время выполнения задачи (3 сек) превышает таймаут (1 сек), канал `ctx.Done()` гарантированно разблокирует ожидающий поток первым.', 'step_by_step': '1. Создадим контекст с таймаутом 20 мс.\n2. Запустим задачу, длящуюся 100 мс.\n3. Зафиксируем время прерывания.\n4. Проверим результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tstart := time.Now()\n\n\t// Таймаут 20 мс\n\tctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)\n\tdefer cancel()\n\n\ttaskDone := make(chan struct{})\n\n\t// Воркер спит 100 мс\n\tgo func() {\n\t\ttime.Sleep(100 * time.Millisecond)\n\t\tclose(taskDone)\n\t}()\n\n\tselect {\n\tcase <-taskDone:\n\t\tfmt.Println("Воркер успел завершиться")\n\tcase <-ctx.Done():\n\t\tfmt.Printf("ctx.Done() сработал раньше воркера (прошло %v)! Ошибка: %v\\n", \n\t\t\ttime.Since(start).Round(time.Millisecond), ctx.Err())\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# ctx.Done() сработал раньше воркера (прошло 20ms)! Ошибка: context deadline exceeded'}], 'under_the_hood': '`select` выбирает первый готовый канал.', 'pitfalls': 'Не забывайте `defer cancel()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова цена вызова context.WithTimeout по аллокациям памяти?»\n**Ответ:** Создается 1 объект `timerCtx` в куче, 1 системный таймер рантайма и 1 буферизованный канал `done` (лениво при первом вызове `Done()`).'}, {'num': 26, 'title': 'Золотое правило пакета context: обязательный defer cancel()', 'task': '**Важнейшее правило**: Всегда вызывайте `cancel()` через `defer` сразу после создания контекста с отменой/таймаутом, чтобы избежать утечки контекста (Goroutine leak).', 'theory': 'Итоговое правило проектирования надежных сервисов: **создание контекста с отменой и вызов `defer cancel()` обязаны идти строго следующими строками друг за другом**.', 'step_by_step': '1. Напишем эталонный шаблон создания отменяемого контекста.\n2. Продемонстрируем защиту от утечек при ранних return.\n3. Проверим компиляцию и выполнение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc safeDatabaseTransaction(parent context.Context) error {\n\t// КАНОНИЧЕСКИЙ ШАБЛОН GO:\n\tctx, cancel := context.WithTimeout(parent, 50*time.Millisecond)\n\tdefer cancel() // 100% гарантия освобождения ресурсов при любом выходе!\n\n\t// Симуляция логики с ранним выходом\n\tif false {\n\t\treturn fmt.Errorf("ранняя ошибка валидации") // defer cancel() выполнится!\n\t}\n\n\tselect {\n\tcase <-time.After(10 * time.Millisecond):\n\t\tfmt.Println("[DB] Транзакция успешно зафиксирована в БД")\n\t\treturn nil\n\tcase <-ctx.Done():\n\t\treturn ctx.Err()\n\t}\n}\n\nfunc main() {\n\terr := safeDatabaseTransaction(context.Background())\n\tif err != nil {\n\t\tfmt.Printf("Ошибка: %v\\n", err)\n\t} else {\n\t\tfmt.Println("Операция завершена с соблюдением всех стандартов безопасности памяти!")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [DB] Транзакция успешно зафиксирована в БД\n# Операция завершена с соблюдением всех стандартов безопасности памяти!'}], 'under_the_hood': '`defer cancel()` гарантирует удаление ссылок из дерева контекстов при любой ветке завершения функции.', 'pitfalls': 'Игнорирование второго возвращаемого значения `cancel` (`ctx, _ := context.WithTimeout(...)`) — частая ошибка новичков.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему компилятор Go разрешает игнорировать функцию cancel через пустой идентификатор ctx, _ := context.WithCancel(...)?»\n**Ответ:** Язык Go не запрещает использование blank identifier `_` для возвращаемых значений, но статические анализаторы (`go vet`, `golangci-lint`) строго помечают такой код как ошибку `lostcancel`.'}]
